CREATE OR REPLACE FUNCTION "public"."confirm_invoice"("p_invoice_no" "text", "p_customer_company_id" "uuid", "p_invoice_date" "date", "p_subtotal" numeric, "p_vat_rate" numeric, "p_vat_amount" numeric, "p_total_amount" numeric, "p_notes" "text", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice_id uuid;
  v_item jsonb;
  v_sort int := 0;
begin
  insert into public.invoices (
    invoice_no, customer_company_id, invoice_date,
    vat_rate, subtotal, vat_amount, total_amount, notes,
    invoice_status, updated_at
  ) values (
    p_invoice_no, p_customer_company_id, p_invoice_date,
    p_vat_rate, p_subtotal, p_vat_amount, p_total_amount, p_notes,
    'DRAFT', now()
  ) returning id into v_invoice_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    insert into public.invoice_items (invoice_id, description, qty, unit, unit_price, sort_order)
    values (
      v_invoice_id,
      v_item->>'description',
      coalesce((v_item->>'qty')::numeric, 1),
      coalesce(v_item->>'unit', 'รายการ'),
      coalesce((v_item->>'unit_price')::numeric, (v_item->>'unitPrice')::numeric, 0),
      v_sort
    );
    v_sort := v_sort + 1;
  end loop;

  return v_invoice_id;
end;
$$;


ALTER FUNCTION "public"."confirm_invoice"("p_invoice_no" "text", "p_customer_company_id" "uuid", "p_invoice_date" "date", "p_subtotal" numeric, "p_vat_rate" numeric, "p_vat_amount" numeric, "p_total_amount" numeric, "p_notes" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  assigned_role public.app_role := 'customer';
begin
  insert into public.profiles (id, email, role)
  values (new.id, new.email, assigned_role);

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


