    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_company_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "amount" numeric,
    "occurred_at" "date" NOT NULL,
    "promised_date" "date",
    "note" "text",
    "source" "text" DEFAULT 'admin_manual'::"text" NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "debt_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['debt_started'::"text", 'receipt_received'::"text", 'promise_to_pay'::"text", 'collection_paused'::"text", 'collection_resumed'::"text", 'interest_waived'::"text", 'penalty_waived'::"text", 'manual_adjustment'::"text", 'debt_closed'::"text"])))
);


ALTER TABLE "public"."debt_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."debt_events" IS 'Append-only event log for debt state changes (Phase B, owner 2026-07-18). No update/delete — corrections are new events (e.g. a wrong freeze is undone by a collection_resumed event, never by editing a row). Debt Engine derives freeze windows and adjusted totals from this history; debt_snapshots.freeze_from/freeze_until remain as a fallback for rows with no events yet.';



COMMENT ON COLUMN "public"."debt_events"."occurred_at" IS 'The real business date the event happened (e.g. the date a customer actually paid), not the date someone typed it into the system.';



CREATE TABLE IF NOT EXISTS "public"."debt_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_company_id" "uuid" NOT NULL,
    "collection_state" "public"."CollectionState" DEFAULT 'CURRENT'::"public"."CollectionState" NOT NULL,
    "total_outstanding" numeric(14,2) DEFAULT 0 NOT NULL,
    "overdue_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "days_overdue" integer DEFAULT 0 NOT NULL,
    "open_invoice_count" integer DEFAULT 0 NOT NULL,
    "last_refreshed_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp(3) without time zone NOT NULL,
    "first_contact_at" timestamp(3) without time zone,
    "debt_start_at" timestamp(3) without time zone,
    "freeze_from" timestamp without time zone,
    "freeze_until" timestamp without time zone,
    "debt_type" "text",
    "legal_basis" "text",
    "reason" "text",
    "calculation_method" "text",
    "vat_status" "text",
    "document_type" "text",
    "remark" "text",
    "source_event_id" "uuid",
    CONSTRAINT "debt_snapshots_debt_type_check" CHECK (("debt_type" = ANY (ARRAY['trade_receivable'::"text", 'collection_reminder'::"text", 'loan'::"text", 'damages'::"text"]))),
    CONSTRAINT "debt_snapshots_document_type_check" CHECK (("document_type" = ANY (ARRAY['invoice'::"text", 'collection_reminder_notice'::"text", 'unsupported'::"text"]))),
    CONSTRAINT "debt_snapshots_vat_status_check" CHECK (("vat_status" = ANY (ARRAY['vat_included'::"text", 'vat_not_applicable'::"text"])))
);


ALTER TABLE "public"."debt_snapshots" OWNER TO "postgres";


COMMENT ON COLUMN "public"."debt_snapshots"."freeze_from" IS 'Interest/penalty accrual pauses starting this date (e.g. a confirmed partial payment or negotiated pause). Null = no freeze.';



COMMENT ON COLUMN "public"."debt_snapshots"."freeze_until" IS 'Freeze ends this date (accrual resumes, NOT retroactively — see engines/debt/tracking.ts). Null + freeze_from set = freeze still open-ended (ongoing).';



COMMENT ON COLUMN "public"."debt_snapshots"."debt_type" IS 'Classifies WHY this debt exists — trade_receivable (ซื้อขายสินค้า/บริการ), collection_reminder (ทวงถามทั่วไป), loan (เงินกู้/เงินยืม), damages (ค่าเสียหาย). Determines which document module is allowed to issue a document for this row — see document_type.';



COMMENT ON COLUMN "public"."debt_snapshots"."vat_status" IS 'vat_included = VAT already recorded in the originating transaction, do not add again. vat_not_applicable = not a VAT transaction (e.g. a collection reminder is not a tax document). No third "not yet decided" state — every row must be classified.';



COMMENT ON COLUMN "public"."debt_snapshots"."document_type" IS 'The ONLY document type allowed to be issued for this debt row, derived from debt_type. trade_receivable -> invoice. collection_reminder -> collection_reminder_notice. loan/damages -> unsupported (no template exists yet — must be flagged, never silently forced through invoice or reminder-card).';



COMMENT ON COLUMN "public"."debt_snapshots"."source_event_id" IS 'The debt_events row that most recently changed this snapshot, if event-sourced. Null for snapshots not yet migrated to the event model.';



