COMMENT ON TABLE "public"."line_profiles" IS 'Who a LINE contact IS (role/organization/trust), not what they said — used to bias document classification (a driver''s photo is probably fuel/weighbridge; a customer''s is probably a payment slip; a supplier''s is probably a tax invoice/DO) instead of guessing blind. Optional per contact — a contact with no row here is simply unclassified (role defaults to external, not silently assumed to be anything specific).';



COMMENT ON COLUMN "public"."line_profiles"."role" IS 'employee/customer/supplier/driver/owner/contractor/accountant/manager/admin/external — biases OCR classification prompts, never forces a classification outright.';



COMMENT ON COLUMN "public"."line_profiles"."trust_level" IS 'verified = identity/role confirmed by a human. unverified = default, no confirmation yet. flagged = known suspicious sender (e.g. sent a fake slip before) — surfaced to reviewers, not auto-blocked.';



COMMENT ON COLUMN "public"."line_profiles"."permissions" IS 'Per-contact permission flags, e.g. {"approve_document": true, "approve_finance": false, "receive_po": true, "receive_invoice": true, "receive_payment": true} — keys are open-ended (Contact Settings popup categories), not a fixed enum, since the owner''s own design expects this to grow over time.';



