COMMENT ON TABLE "public"."partner_payable_requests" IS 'Owner Dispatcher partner-payable cascade: Trigger (a partner invoice/bill arrives) -> notify owner -> owner acknowledges (button) -> owner transfers + sends slip in chat (real Trigger for stage 2) -> Consensus (bank_notifications, valid here since the owner is the initiator) -> owner_acknowledged/paid_confirmed/completed. Never guesses: paid_confirmed only set once a real slip amount matches this row within +-5 THB.';



