);


ALTER TABLE "public"."receipt_documents" OWNER TO "postgres";


COMMENT ON COLUMN "public"."receipt_documents"."status" IS 'ai_read (Pending Review — a slip was classified, awaiting human confirmation) | waiting_bank_confirmation (customer claims payment, no slip/evidence yet) | confirmed (a human verified it — created a receipt_received debt event) | rejected (mismatch/no real transfer found).';



COMMENT ON COLUMN "public"."receipt_documents"."sender_name" IS 'Name of the transferring account holder, as printed on the slip. Only meaningful for document_type=transfer_slip.';



COMMENT ON COLUMN "public"."receipt_documents"."sender_bank" IS 'Bank name printed on the slip (e.g. "กสิกรไทย"). Only meaningful for document_type=transfer_slip.';



COMMENT ON COLUMN "public"."receipt_documents"."reference_number" IS 'Transaction/reference number printed on the slip, if any — the strongest single field for cross-matching against a second evidence source once one exists.';



COMMENT ON COLUMN "public"."receipt_documents"."transaction_datetime" IS 'The real transfer date/time as printed on the slip (not document_date, which the existing OCR schema already uses for a coarser date-only value on other document types).';



COMMENT ON COLUMN "public"."receipt_documents"."customer_company_id" IS 'Which company this slip is claimed to be a payment from — matched via the same line_user_id -> company_line_links path every other consumer uses (see engines/line-webhook-v2/engines/relationship-qa.ts). Null if no match found; never guessed.';



COMMENT ON COLUMN "public"."receipt_documents"."matched_debt_event_id" IS 'The debt_events row created when a human confirmed this slip (status became confirmed). Null while still ai_read/rejected.';



COMMENT ON COLUMN "public"."receipt_documents"."payment_method" IS 'How the customer says they paid: cash / transfer / qr / cheque. Only meaningful once a human or a second evidence source confirms it — not guessed from a slip photo alone.';



COMMENT ON COLUMN "public"."receipt_documents"."sender_account_number" IS 'Transferring account number, if visible on the slip. Only meaningful for document_type=transfer_slip.';



COMMENT ON COLUMN "public"."receipt_documents"."receiving_bank" IS 'Our own bank the money should land in, for cross-checking against a future bank-statement/API source. Not read from the slip — set from company settings once that comparison exists.';



COMMENT ON COLUMN "public"."receipt_documents"."receiving_account_number" IS 'Our own account number, same purpose as receiving_bank.';



COMMENT ON COLUMN "public"."receipt_documents"."confirmed_by" IS 'Who moved this row to confirmed/rejected — an admin email (see the confirm/reject routes) today; reserved for "ai" or a specific verification-engine identity once a real second source exists to auto-verify against.';



COMMENT ON COLUMN "public"."receipt_documents"."receiving_account_name" IS 'Name on our own receiving bank account, alongside receiving_bank/receiving_account_number — completes the "which account did this land in" record for later audit search.';



COMMENT ON COLUMN "public"."receipt_documents"."verification_level" IS '1=LINE claim only, 2=+OCR slip read, 3=+bank notification email (unbuilt), 4=+bank statement/API (unbuilt). Reflects how much REAL evidence exists, not a guess at what should exist.';



COMMENT ON COLUMN "public"."receipt_documents"."payment_verified" IS 'True only once every currently-available verification level agrees AND a human (or, once levels 3/4 exist, the verification engine) has confirmed it. Distinct from status=confirmed for query/audit convenience — e.g. "find every real, verified payment of ฿16,856.53 on 2026-07-18" without needing to know the status vocabulary.';



CREATE TABLE IF NOT EXISTS "public"."schema_change_log" (
    "id" bigint NOT NULL,
    "phase" "text" NOT NULL,
    "command_tag" "text" NOT NULL,
    "object_type" "text",
    "object_identity" "text",
    "executed_by" "text" DEFAULT CURRENT_USER NOT NULL,
    "client_addr" "inet",
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "schema_change_log_phase_check" CHECK (("phase" = ANY (ARRAY['start'::"text", 'end'::"text"])))
);


ALTER TABLE "public"."schema_change_log" OWNER TO "postgres";


ALTER TABLE "public"."schema_change_log" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."schema_change_log_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."standalone_document_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid" NOT NULL,
    "description" "text" NOT NULL,
    "qty" numeric DEFAULT 1 NOT NULL,
    "unit" "text" DEFAULT 'รายการ'::"text" NOT NULL,
    "unit_price" numeric DEFAULT 0 NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."standalone_document_items" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."standalone_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_no" "text" NOT NULL,
    "document_type" "public"."DocumentType" NOT NULL,
    "document_date" timestamp(3) without time zone NOT NULL,
    "customer_company_id" "uuid",
    "partner_company_id" "uuid",
    "project_id" "uuid",
    "customer_order_id" "uuid",
    "reference_no" "text",
    "recipient_address" "text",
    "notes" "text",
    "vat_rate" numeric(6,4) DEFAULT 0.07 NOT NULL,
    "subtotal" numeric(14,2) NOT NULL,
    "vat_amount" numeric(14,2) NOT NULL,
    "total_amount" numeric(14,2) NOT NULL,
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp(3) without time zone NOT NULL
);


ALTER TABLE "public"."standalone_documents" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."vehicle_types" (
